<body>
    <div id="main-container"></div>

    <script>
        function getMoodTheme(emotion) {
            const positive = ['开心', '快乐', '微笑', '温柔', '温暖', '感动', '欣慰', '得意', '俏皮', '调皮', '活泼', '兴奋', '期待', '害羞', '脸红', '甜蜜', '灿烂', '阳光', '自信', '惊喜', '激动', '爱慕', '心动', '傲娇', '天然', '元气'];
            const negative = ['难过', '悲伤', '失落', '沮丧', '忧郁', '孤独', '愤怒', '生气', '恼火', '嫉妒', '焦虑', '恐惧', '害怕', '不安', '病娇', '黑化', '绝望', '悲悯'];
            const dramatic = ['惊喜', '感动', '激动', '震撼', '疯狂', '痴迷', '崇拜', '爱慕', '心动', '傲娇', '病娇', '黑化', '威严', '庄严'];
            if (dramatic.includes(emotion)) return 'dramatic';
            if (positive.includes(emotion)) return 'positive';
            if (negative.includes(emotion)) return 'negative';
            return 'neutral';
        }
        function splitEmotions(raw) {
            if (!raw || typeof raw !== 'string') return [];
            return raw.split(/[,，、\/\s|]+/).map(s => s.trim()).filter(s => s.length > 0);
        }
        function init() {
            try {
                let emotionRaw = `$1`;
                let textRaw = `$2`;
                const emotionList = splitEmotions(emotionRaw);
                const finalEmotions = emotionList.length > 0 ? emotionList : ['平静'];
                const text = textRaw.trim();
                if (!text || text === '$2') return;
                const avatarUrl = 'https://zora404.dpdns.org/file/1787590937509_image.png';
                let moodsHtml = '';
                finalEmotions.forEach((emotion, index) => {
                    const theme = getMoodTheme(emotion);
                    moodsHtml += `<span class="lilith-mood mood-${theme}" style="animation: fadeInLilith 0.4s ease ${index * 50}ms both;">${emotion}</span>`;
                });
                const html = `
                    <div class="lilith-wrapper">
                        <span class="lilith-corner tl"></span><span class="lilith-corner tr"></span>
                        <div class="lilith-avatar" id="lilith-avatar-container">
                            <div class="avatar-ring"></div>
                            <div class="avatar-fallback">⌛</div>
                            <img src="${avatarUrl}" alt="盲目的莉莉娅" loading="lazy" onload="this.classList.add('img-loaded'); document.getElementById('lilith-avatar-container').classList.add('has-img');" onerror="this.remove();">
                        </div>
                        <div class="lilith-dialogue">
                            <div class="lilith-name-row">
                                <span class="lilith-name">✧ 盲目的莉莉娅</span>
                                <span class="lilith-title-tag">回溯的英灵 · 时之祭司</span>
                                <div class="lilith-moods">${moodsHtml}</div>
                            </div>
                            <div class="lilith-text-card"><div class="lilith-text">${text}</div></div>
                            <div class="lilith-footer"><span class="line"></span>⌛ ✦ 时间回响 ✦ ⌛<span class="line r"></span></div>
                        </div>
                    </div>`;
                document.getElementById('main-container').innerHTML = html;
            } catch (error) {
                console.error('[莉莉娅渲染] 错误:', error);
            }
        }
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
    </script>
</body>
